if(qEnd(pq[0],pq[1])>=st&&pend(pk)>0)o.push({t:'Overdue: '+pend(pk)+' checks from Q'+pq[1]+' '+pq[0]+' still open'});
if(q==1&&!R.rec[y-1]&&new Date(y-1,11,31)>=st)o.push({t:'Year-end reconciliation for '+(y-1)+' is overdue'});
