const su=u=>/^https?:\/\//i.test(u||'')?u:'';
let FD=[],ADV={pages:[]},CUR=-1,ri=0;const EPS=[],AU=new Audio(),RATES=[1,1.25,1.5,1.75,2];
const tm=s=>isFinite(s)?Math.floor(s/60)+':'+String(Math.floor(s%60)).padStart(2,'0'):'0:00';
const hl=p=>p.h||(p.x||'').split(/(?<=[.!?])\s/)[0].slice(0,110);
const ini=n=>((n||'').match(/\b\w/g)||[]).slice(0,2).join('').toUpperCase();
function currentArea(){return (typeof Areas!=='undefined'&&Areas.areaById(S.area||''))||(typeof Areas!=='undefined'&&Areas.areaById('au'))||{id:'au',name:'All of Australia'}}
function curatedNews(){const area=currentArea();const q=(V.q||'').toLowerCase();const items=[...base()].filter(p=>sinfo(p).s==='news').map(p=>{const si=sinfo(p);return {p,text:hl(p)+' '+(p.x||''),source:si.n}}).filter(item=>!q||(item.text+' '+item.source).toLowerCase().includes(q));if(typeof Areas==='undefined')return {rows:items.map(item=>item.p).sort((a,b)=>(a.m||0)-(b.m||0)).slice(0,12),note:'',empty:'News snapshots show here after the next check.'};const pack=Areas.curated(items,area.id);const rows=pack.items.map(item=>item.p).sort((a,b)=>(a.m||0)-(b.m||0)).slice(0,12);const from=pack.widened?Areas.areaById(pack.from):null;const note=pack.widened&&from?'Nothing new from '+area.name+' in this check. Showing '+from.name+'.':area.id==='au'?'Driving news across Australia. Choose an area for a local view.':area.id==='nz'?'Driving news across New Zealand.':'Driving news for '+area.name+'.';const empty=rows.length?'':pack.widened&&from?'No driving news for '+from.name+' in this check.':'No driving news for '+area.name+' in this check.';return {rows,note,empty}}
function setArea(id){if(typeof Areas!=='undefined'&&!Areas.areaById(id))return;S.area=id;sv();drawMag();drawTk()}
function areaSelect(){if(typeof Areas==='undefined')return '';const chosen=currentArea().id;const groups=[];Areas.AREAS.forEach(area=>{let group=groups.find(item=>item.name===area.group);if(!group){group={name:area.group,items:[]};groups.push(group)}group.items.push(area)});return `<label class="area-pick">Area <select id="area" onchange="setArea(this.value)">${groups.map(group=>`<optgroup label="${esc(group.name)}">${group.items.map(area=>`<option value="${esc(area.id)}"${area.id===chosen?' selected':''}>${esc(area.name)}</option>`).join('')}</optgroup>`).join('')}</select></label>`}
function tile(p){const si=sinfo(p);return`<button class="tile" onclick="rd('${js(p.id)}')"><div class="ph" style="background:linear-gradient(135deg,${col(si.n)},${col(si.n+'x')})"><span class="pi">${esc(ini(si.n))}</span>${su(p.img)?`<img loading="lazy" referrerpolicy="no-referrer" alt="" src="${esc(su(p.img))}" onerror="this.remove()">`:''}</div><div class="tb"><div class="sub">${ico(si.s,si.n,si.logo)}<b>${esc(si.n)}</b> · ${ago(p.m)}</div><div class="ht">${esc(hl(p))}</div><div class="sub">${esc((p.x||'').slice(0,140))}</div></div></button>`}
function pageLink(href,label){return `<a class="page-link" href="${esc(href)}" target="_blank" rel="noopener noreferrer">${esc(label)}</a>`}
function advocatePagesBlock(){const pages=(ADV&&ADV.pages)||[];const main=pages.find(p=>/drivers advocate/i.test(p.name||''))||{};const cells=[pageLink('https://tdaau.com/',"The Driver's Advocate website"),pageLink(main.facebook||'https://www.facebook.com/groups/thedriversadvocate/',"The Driver's Advocate main Facebook page")];pages.forEach(p=>{if(/drivers advocate/i.test(p.name||''))return;const name=p.name||'Page';cells.push(p.site?pageLink(p.site,name+' website'):'<span class="page-link"></span>');cells.push(p.facebook?pageLink(p.facebook,name+' Facebook page'):'<span class="page-link"></span>')});return `<section class="card"><h3>The Driver's Advocate</h3><div class="page-cols">${cells.join('')}</div></section>`}
function magView(){const m=$('#m');if(!m)return;m.innerHTML=offNote()+`<section class="card" style="padding-bottom:4px"><div class="area-row"><h3>Daily driving news</h3>${areaSelect()}</div><p class="sub" id="area-note"></p>${sourceStrip()}</section><div id="mag" class="mag"></div>`+advocatePagesBlock();drawMag()}
function drawMag(){const e=$('#mag');if(!e)return;const pack=curatedNews();const note=$('#area-note');if(note)note.textContent=pack.note;e.innerHTML=pack.rows.length?pack.rows.map(tile).join(''):'<div class="card mut">'+esc(pack.empty)+'</div>'}
function rd(id){const p=all().find(x=>String(x.id)==String(id));if(!p)return;const si=sinfo(p),e=document.createElement('div');e.id='rd';e.style.cssText='position:fixed;inset:0;z-index:60;background:rgba(0,0,0,.6);overflow:auto;padding:16px';e.onclick=ev=>{if(ev.target==e)e.remove()};
e.innerHTML=`<div class="card" style="max-width:640px;margin:20px auto;padding:0;overflow:hidden">${su(p.img)?`<img referrerpolicy="no-referrer" alt="" style="width:100%;max-height:340px;object-fit:cover" src="${esc(su(p.img))}" onerror="this.remove()">`:''}<div style="padding:16px"><div class="sub">${ico(si.s,si.n,si.logo)}<b>${esc(si.n)}</b> · ${ago(p.m)}</div><h2 style="margin:8px 0">${esc(hl(p))}</h2><p>${esc(p.x||'')}</p><div class="bar" style="margin-top:10px">${su(p.url)?`<a class="btn" target="_blank" rel="noopener" href="${esc(su(p.url))}">Read on ${esc(si.n)}</a>`:''}<button class="btn g" onclick="this.closest('#rd').remove()">Close</button></div></div></div>`;document.body.appendChild(e)}
// podcast
function pView(){$('#m').innerHTML=`<div class="card"><h3>🎧 Podcast</h3>${EPS.length?'<div class="mut">Tap an episode. Controls stay at the bottom while you browse. Listen only when it is safe to do so.</div>':'<div class="note">No episodes yet. An admin adds the podcast RSS link in Admin &gt; Auto-fetch feeds (type: Podcast).</div>'}<div id="eps"></div></div>`;drawEps()}
function drawEps(){const e=$('#eps');if(!e)return;e.innerHTML=EPS.map((x,i)=>`<div class="lk" style="cursor:pointer" onclick="pl(${i})"><button class="btn ${i==CUR?'':'g'}" style="min-width:48px">${i==CUR&&!AU.paused?'⏸':'▶'}</button><div style="flex:1"><b>${esc(x.h)}</b><div class="sub">${esc(x.show||'')} · ${ago(x.m)}${x.dur?' · '+esc(x.dur):''}</div></div></div>`).join('')}
function sameUrl(a,b){try{return !!a&&!!b&&new URL(a,location.href).href===new URL(b,location.href).href}catch(e){return a===b}}
function pl(i){if(i<0||i>=EPS.length)return;if(i==CUR){tp2();return}CUR=i;const x=EPS[i];AU.src=x.audio;AU.playbackRate=RATES[ri];AU.play().catch(()=>{});mini();if('mediaSession' in navigator){try{navigator.mediaSession.metadata=new MediaMetadata({title:x.h,artist:x.show||'Podcast',artwork:su(x.img)?[{src:su(x.img)}]:[]})}catch(e){}}}
const tp2=()=>{AU.paused?AU.play():AU.pause()};
const sk=s=>{AU.currentTime=Math.max(0,Math.min(AU.duration||1e9,AU.currentTime+s))};
function rate(){ri=(ri+1)%RATES.length;AU.playbackRate=RATES[ri];mini()}
function mini(){const b=$('#pl');if(CUR<0||!EPS[CUR]){b.style.display='none';return}const x=EPS[CUR];b.style.display='flex';b.innerHTML=`<div class="pt"><b>${esc(x.h)}</b><div class="sub"><span id="pc">${tm(AU.currentTime)}</span> / ${tm(AU.duration)}</div><input type="range" id="pr2" min="0" max="1000" value="0" oninput="AU.currentTime=AU.duration*this.value/1000"></div><button onclick="sk(-15)">⏪ 15</button><button class="pp" onclick="tp2()">${AU.paused?'▶':'⏸'}</button><button onclick="sk(30)">30 ⏩</button><button onclick="rate()">${RATES[ri]}×</button><button onclick="pl(CUR+1)">⏭</button>`;drawEps()}
AU.onplay=AU.onpause=AU.onloadedmetadata=()=>mini();AU.onended=()=>pl(CUR+1);
AU.ontimeupdate=()=>{const c=$('#pc'),r=$('#pr2');if(c)c.textContent=tm(AU.currentTime);if(r&&AU.duration)r.value=AU.currentTime/AU.duration*1000};
if('mediaSession' in navigator){[['play',()=>AU.play()],['pause',()=>AU.pause()],['seekbackward',()=>sk(-15)],['seekforward',()=>sk(30)],['nexttrack',()=>pl(CUR+1)],['previoustrack',()=>pl(CUR-1)]].forEach(([a,f])=>{try{navigator.mediaSession.setActionHandler(a,f)}catch(e){}})}
// Facebook page plugins (Facebook's own embed)
const FBCARD=`<div class="card"><h3>Facebook pages</h3><div class="mut">Shown by Facebook's own page plugin, so Facebook decides what appears.</div><div class="bar" style="margin-top:8px">${['otrpodcastaus','ontheroadpodcast'].map(h=>`<iframe title="${h}" src="https://www.facebook.com/plugins/page.php?href=${encodeURIComponent('https://www.facebook.com/'+h)}&tabs=timeline&width=340&height=500&small_header=true&adapt_container_width=true&hide_cover=true&show_facepile=false" width="340" height="500" style="border:0;max-width:100%" loading="lazy"></iframe>`).join('')}</div></div>`;
// feed admin
const fl=()=>{const e=$('#flist');if(e)e.innerHTML=FD.map(f=>`<div class="lk">${ico(f.src=='podcast'?'web':f.src,f.name,f.logo||logoFor(f.name))}<span style="flex:1"><b>${esc(f.name)}</b> <span class="sub">${esc(f.src)} · ${esc(f.url)}</span></span><button class="btn g" onclick="fDel('${f.id}')">Remove</button></div>`).join('')||'<div class="mut">No feeds yet.</div>'};
async function fAdd(){const u=$('#fu').value.trim(),n=$('#fn').value.trim();if(!/^https?:\/\//i.test(u)||!n){$('#fr').textContent=' Enter a full feed URL and a name';return}try{await DB.collection('feeds').add({url:u,name:n,src:$('#fs').value,topic:$('#ft').value,g:+$('#fg').value});$('#fu').value='';$('#fn').value='';$('#fr').textContent=' Added. Click Fetch now.'}catch(e){$('#fr').textContent=' Failed'}}
async function fDel(id){try{await DB.doc('feeds/'+id).delete()}catch(e){}}
async function fNow(){$('#fr').textContent=' Fetching…';try{const r=await api('POST','/api/refresh');await load();$('#fr').textContent=r.busy?' Already running':' '+r.added+' new, '+(r.updated||0)+' updated'+(r.errors&&r.errors.length?'. Problems: '+r.errors.join('; '):'')}catch(e){$('#fr').textContent=' Failed'}}
// ---- admin + shared live data
const sorted=()=>[...(PS||[])].sort((a,b)=>(b.ord||0)-(a.ord||0));
const P1=id=>(PS||[]).find(p=>p.id==id);
const er=e=>{const x=$('#ae');if(x)x.textContent=' Failed: '+((e&&e.code)||e)};
const gOpts=s=>'<option value="-1" '+(s==-1?'selected':'')+'>— No group (news / other) —</option>'+G.map(g=>`<option value="${g.id}" ${g.id==s?'selected':''}>${esc(gn(g))}</option>`).join('');
const tOpts=s=>TOP.map(t=>`<option ${t==s?'selected':''}>${t}</option>`).join('');
function refresh(){const typing=document.activeElement&&document.activeElement.closest&&document.activeElement.closest('#m');if(V.view=='traffic'){if(!typing)trafficView()}else if(V.view=='mag'){if(!typing)drawMag()}else if(V.view=='adm'){if(!typing)drawAdmin()}}
function admView(){$('#m').innerHTML=`<div class="card"><h3>Oversight <button class="btn g" onclick="logout()">Log out</button></h3><p class="sub">Signed in as RoadHub_Admin. Correct a post or reply below, or keep a recovery file so the hub can be put back if the data is lost. This login is built in, so it still works after the data is gone.</p><button class="btn" onclick="downloadBackup()">Download recovery file</button> <button class="btn g" onclick="$('#rf').click()">Restore recovery file</button><input id="rf" type="file" accept="application/json,.json" hidden onchange="restoreBackup(this)"><span id="rr" class="mut"></span></div>
<div class="card"><h3>Add a post</h3><div class="bar"><select id="ag">${gOpts(0)}</select><select id="at">${tOpts('')}</select><input class="f" id="aa" placeholder="Author name"><select id="as">${sOpts('fb')}</select><input class="f" id="asn" placeholder="Source name (e.g. a news outlet)"><input class="f" id="au" placeholder="Original Facebook post link (optional)"><input class="f" id="ad" type="datetime-local" title="Posted at (blank = now)"><input class="f" id="al" type="number" min="0" placeholder="Likes" style="width:80px"><input class="f" id="ac" type="number" min="0" placeholder="Comments" style="width:100px"></div><textarea id="ax" rows="4" style="width:100%;margin:8px 0" placeholder="Paste the post text"></textarea><button class="btn" onclick="aAdd()">Publish to everyone</button><span id="ae" class="mut"></span></div>
<div class="card"><h3>Posts (curated order, top first)</h3><div id="alist"></div></div>
<div class="card"><h3>Replies</h3><div id="rlist"></div></div>
<div class="card"><h3>Auto-fetch feeds <span class="sub">(checked every 30 min)</span></h3><div class="bar"><input class="f" id="fu" placeholder="Feed URL (RSS or Atom)" style="flex:1;min-width:200px"><input class="f" id="fn" placeholder="Name, e.g. TDA website"><select id="fs"><option value="main">Drivers Advocate site</option><option value="news">News outlet</option><option value="web">Other website</option><option value="podcast">Podcast (audio)</option></select><select id="ft">${tOpts('Industry News')}</select><select id="fg">${gOpts(-1)}</select><button class="btn" onclick="fAdd()">Add feed</button><button class="btn g" onclick="fNow()">Fetch now</button></div><span id="fr" class="mut"></span><div id="flist"></div></div>
<div class="card"><h3>Ticker headlines</h3><div class="bar"><select id="tkd"><option>NEWS</option><option>TRENDING</option><option>POST</option></select><select id="tks">${sOpts('news')}</select><input class="f" id="tkn" placeholder="Source name" style="width:140px"><input class="f" id="tx" placeholder="Headline" style="flex:1"><button class="btn" onclick="tAdd()">Add</button></div><div id="tl"></div></div>`;drawAdmin()}
function drawAdmin(){const e=$('#alist');if(!e)return;const L=sorted();
e.innerHTML=L.length?L.map(p=>ED==p.id?`<div class="lk" style="display:block"><div class="bar"><select id="eg">${gOpts(p.g)}</select><select id="et">${tOpts(p.t)}</select><input class="f" id="ea" value="${esc(p.a)}"><select id="es">${sOpts(sinfo(p).s)}</select><input class="f" id="esn" value="${esc(p.srcName||'')}" placeholder="Source name"><input class="f" id="eh" value="${esc(p.h||'')}" placeholder="Headline"><input class="f" id="eu" value="${esc(p.url||'')}" placeholder="Link"></div><textarea id="ex" rows="3" style="width:100%;margin:6px 0">${esc(p.x||'')}</textarea><button class="btn" onclick="aSave('${p.id}')">Save</button> <button class="btn g" onclick="ED=null;drawAdmin()">Cancel</button></div>`:`<div class="lk"><div style="flex:1;min-width:200px"><b>${p.pin?'📌 ':''}${esc(p.a)}</b> <span class="sub">${ico(sinfo(p).s,sinfo(p).n,sinfo(p).logo)}${esc(sinfo(p).n)} · ${esc(gn(gOf(p)))} · ${p.t} · ${ago(p.m)}</span><div>${esc(p.x)}</div></div><button class="btn g" onclick="mv('${p.id}',-1)">▲</button><button class="btn g" onclick="mv('${p.id}',1)">▼</button><button class="btn g" onclick="pn('${p.id}')">${p.pin?'Unpin':'Pin'}</button><button class="btn g" onclick="ED='${p.id}';drawAdmin()">Edit</button><button class="btn g" onclick="dl('${p.id}')">${CF==p.id?'Sure?':'Delete'}</button></div>`).join(''):'<div class="mut">No posts yet. <button class="btn g" onclick="aSeed()">Add sample posts</button></div>';
const replies=$('#rlist');if(replies){const rows=[...(CM||[])].sort((a,b)=>(b.at||0)-(a.at||0));replies.innerHTML=rows.length?rows.map(c=>RF==c.id?`<div class="lk" style="display:block"><input class="f" id="ca" value="${esc(c.a||'')}" placeholder="Name"> <textarea id="cx" rows="2" style="width:100%;margin:6px 0">${esc(c.x||'')}</textarea><button class="btn" onclick="cSave('${js(c.id)}')">Save reply</button> <button class="btn g" onclick="RF=null;drawAdmin()">Cancel</button></div>`:`<div class="lk"><div style="flex:1;min-width:200px"><b>${esc(c.a||'')}</b><div>${esc(c.x||'')}</div></div><button class="btn g" onclick="RF='${js(c.id)}';drawAdmin()">Fix</button><button class="btn g" onclick="cdl('${js(c.id)}')">Delete</button></div>`).join(''):'<div class="mut">No replies yet.</div>'}
fl();const t=$('#tl');if(t)t.innerHTML=(TK||[]).map(x=>`<div class="lk"><span style="flex:1">${ico(x.src||'news',x.srcName,x.logo||logoFor(x.srcName))}<b>${esc(x.kind)}</b> ${esc(x.text)}</span><button class="btn g" onclick="tdl('${x.id}')">Delete</button></div>`).join('')||'<div class="mut">No custom headlines yet (sample ticker shown).</div>'}
async function aAdd(){try{const x=$('#ax').value.trim();if(!x)return;const v=$('#ad').value,at=v?new Date(v).getTime():Date.now();await DB.collection('posts').add({g:+$('#ag').value,a:$('#aa').value.trim()||'Admin',t:$('#at').value,x,url:$('#au').value.trim(),src:$('#as').value,srcName:$('#asn').value.trim(),l:+$('#al').value||0,c:+$('#ac').value||0,pin:false,at,ord:Date.now()});$('#ax').value='';$('#ae').textContent=' Published ✓'}catch(e){er(e)}}
async function pn(id){try{await DB.doc('posts/'+id).update({pin:!P1(id).pin})}catch(e){er(e)}}
async function aSave(id){try{await DB.doc('posts/'+id).update({g:+$('#eg').value,t:$('#et').value,a:$('#ea').value,src:$('#es').value,srcName:$('#esn').value.trim(),h:$('#eh').value.trim(),url:$('#eu').value.trim(),x:$('#ex').value});ED=null;drawAdmin()}catch(e){er(e)}}
async function cSave(id){try{const x=$('#cx').value.trim();if(!x)return;await DB.doc('comments/'+id).update({a:$('#ca').value.trim()||'Driver',x});RF=null;drawAdmin()}catch(e){er(e)}}
async function cdl(id){try{await DB.doc('comments/'+id).delete();RF=null}catch(e){er(e)}}
async function downloadBackup(){const el=$('#rr');try{const data=await api('GET','/api/admin/backup');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(data)],{type:'application/json'}));a.download='goroadhub-recovery.json';a.click();URL.revokeObjectURL(a.href);if(el)el.textContent=' Recovery file downloaded.'}catch(e){if(el)el.textContent=' Could not download the recovery file.'}}
async function restoreBackup(input){const el=$('#rr'),file=input.files&&input.files[0];input.value='';if(!file)return;if(!confirm('Put posts, replies, feeds, episodes, and headlines back from this file?'))return;try{const data=JSON.parse(await file.text());const r=await api('POST','/api/admin/restore',data);const n=r.restored||{};if(el)el.textContent=' Restored '+(n.posts||0)+' posts and '+(n.comments||0)+' replies.';await load()}catch(e){if(el)el.textContent=' That file could not be restored.'}}
async function dl(id){if(CF!=id){CF=id;drawAdmin();return}CF=null;try{await DB.doc('posts/'+id).delete()}catch(e){er(e)}}
async function mv(id,d){const L=sorted(),i=L.findIndex(p=>p.id==id),o=x=>(x&&x.ord)||0;let n;if(d<0){if(i<1)return;n=L[i-2]?(o(L[i-2])+o(L[i-1]))/2:o(L[i-1])+1000}else{if(i<0||i>=L.length-1)return;n=L[i+2]?(o(L[i+1])+o(L[i+2]))/2:o(L[i+1])-1000}try{await DB.doc('posts/'+id).update({ord:n})}catch(e){er(e)}}
async function aSeed(){try{for(const p of P.slice(0,24)){const at=Date.now()-p.m*6e4;await DB.collection('posts').add({g:p.g,a:p.a,t:p.t,x:p.x,url:'',l:p.l,c:p.c,pin:false,at,ord:at})}}catch(e){er(e)}}
async function tAdd(){const x=$('#tx').value.trim();if(!x)return;try{await DB.collection('ticker').add({kind:$('#tkd').value,text:x,src:$('#tks').value,srcName:$('#tkn').value.trim(),at:Date.now()});$('#tx').value=''}catch(e){er(e)}}
async function tdl(id){try{await DB.doc('ticker/'+id).delete()}catch(e){er(e)}}
const api=(m,u,b)=>fetch(u,{method:m,headers:{'Content-Type':'application/json'},body:b?JSON.stringify(b):undefined}).then(async r=>{const d=await r.json().catch(()=>({}));return r.ok?d:Promise.reject({code:r.status,error:d.error})});
function snapAge(){if(!SNAP||!SNAP.at)return 'earlier';const mins=Math.max(0,Math.round((Date.now()-SNAP.at)/60000));if(mins<1)return 'just now';if(mins<60)return mins+' min ago';const h=Math.round(mins/60);if(h<48)return h+' hour'+(h>1?'s':'')+' ago';const d=Math.round(h/24);return d+' day'+(d>1?'s':'')+' ago'}
function offNote(){if(!OFFLINE)return '';const when=SNAP&&SNAP.at?' Showing headlines saved '+esc(snapAge())+'.':'';return '<div class="offbar">No reception.'+when+'</div>'}
function slimPost(p){return {id:p.id,g:p.g,a:p.a,t:p.t,x:p.x,h:p.h,url:p.url,img:p.img,src:p.src,srcName:p.srcName,logo:p.logo,l:p.l,c:p.c,pin:p.pin,at:p.at,ord:p.ord,auto:p.auto,driver:p.driver}}
function saveSnap(){try{const posts=(PS||[]).slice(0,40).map(slimPost),comments=(CM||[]).filter(c=>posts.some(p=>String(p.id)===String(c.postId))).slice(0,150);SNAP={at:Date.now(),posts,ticker:TK||[],comments,traffic:(TR||[]).slice(0,20).map(p=>({id:p.id,h:p.h,x:p.x,url:p.url,src:p.src||'traffic',srcName:p.srcName,logo:p.logo,a:p.a,at:p.at,auto:true})),episodes:(EPS||[]).slice(0,20).map(x=>({h:x.h,x:x.x,audio:x.audio,img:x.img,at:x.at,dur:x.dur,url:x.url,show:x.show}))};localStorage.setItem('rh-snap',JSON.stringify(SNAP))}catch(e){}}
function restoreSnap(){let raw;try{raw=JSON.parse(localStorage.getItem('rh-snap')||'')}catch(e){return false}if(!raw||!Array.isArray(raw.posts))return false;SNAP=raw;const age=o=>({...o,m:Math.max(0,Math.round((Date.now()-(o.at||Date.now()))/6e4))});PS=raw.posts.map(age);TK=raw.ticker||[];CM=raw.comments||[];TR=Array.isArray(raw.traffic)?raw.traffic.map(age):[];EPS.splice(0,EPS.length,...(raw.episodes||[]).map(age).sort((x,y)=>(y.at||0)-(x.at||0)));return true}
function storyPool(){return [...base()].filter(p=>sinfo(p).s!=='traffic')}
function latestStories(){return storyPool().filter(p=>!p.auto).sort((a,b)=>(a.m||0)-(b.m||0)).slice(0,4)}
function webStories(){return storyPool().filter(p=>['main','web'].includes(sinfo(p).s)||(p.auto&&sinfo(p).s!=='news')).sort((a,b)=>(a.m||0)-(b.m||0)).slice(0,4)}
function newsStories(){return storyPool().filter(p=>p.auto&&sinfo(p).s==='news').sort((a,b)=>(a.m||0)-(b.m||0)).slice(0,6)}
function sourceStrip(kind){const rows=(OUTLETS||[]).filter(o=>kind?o.kind===kind:o.kind!=='traffic');if(!rows.length)return '';return `<div class="src-row">${rows.map(o=>`<a class="src-logo" href="${esc(o.home)}" title="${esc(o.name)}" target="_blank" rel="noopener noreferrer"><img alt="${esc(o.name)}" referrerpolicy="no-referrer" src="${esc(o.logo)}" onerror="this.parentNode.remove()"></a>`).join('')}</div>`}
function newsCard(){const rows=newsStories();const hits=rows.map(p=>{const si=sinfo(p);return `<button class="story-hit" onclick="rd('${js(p.id)}')"><span class="sub">${ico(si.s,si.n,si.logo)}${esc(si.n)} · ${p.m<2?'just now':ago(p.m)}</span><b>${esc(hl(p))}</b></button>`}).join('');return `<div class="card" style="padding:0;overflow:hidden"><h3 style="padding:14px 14px 0">Transport news</h3><p class="sub" style="padding:0 14px">Daily driving news for Australia and New Zealand, kept to transport stories. news.com.au headlines come from the public Google News listing of news.com.au. The same headlines run in the ticker.</p>${sourceStrip()}${hits||'<p class="mut" style="padding:14px">Headlines show here after the next check.</p>'}</div>`}
function trafficView(){const rows=(TR||[]).slice().sort((a,b)=>(a.m||0)-(b.m||0));const live=(OUTLETS||[]).find(o=>o.kind==='traffic');$('#m').innerHTML=offNote()+`<div class="card"><h3>${live?ico('traffic',live.name,live.logo):''} Live traffic</h3><p class="sub">Open incident reports from Transport for NSW.</p>${sourceStrip('traffic')}${rows.length?rows.map(p=>{const si=sinfo(p);const open=su(p.url);return `<article class="traffic-row"><div class="sub">${ico(si.s,si.n,si.logo)}<b>${esc(si.n)}</b> · ${p.m<2?'just now':ago(p.m)}</div><b class="ht">${esc(hl(p))}</b><p>${esc(p.x||'')}</p>${open?`<a href="${esc(open)}" target="_blank" rel="noopener noreferrer">Open the report</a>`:''}</article>`}).join(''):'<p class="mut">No open incidents in the latest check.</p>'}<p class="sub">Source: <a href="https://www.livetraffic.com/" target="_blank" rel="noopener noreferrer">Live Traffic NSW</a>. Data © Transport for NSW, <a href="https://opendata.transport.nsw.gov.au/dataset/live-traffic-hazards" target="_blank" rel="noopener noreferrer">open data</a>.</p></div>`}
function advocateWidgets(){const pages=(ADV&&ADV.pages)||[],stories=webStories();
return `<div class="card"><h3>The Driver's Advocate</h3><p class="sub">Doors from tdaau.com. A news feed added in Admin appears here too. Facebook group posts open on Facebook, because Facebook does not share a group feed with other apps.</p>${stories.length?stories.map(p=>`<button class="story-hit" onclick="rd('${js(p.id)}')"><span class="sub">${ico(sinfo(p).s,sinfo(p).n,sinfo(p).logo)}${esc(sinfo(p).n)} · ${p.m<2?'just now':ago(p.m)}</span><b>${esc(hl(p))}</b></button>`).join(''):''}<div class="adv-grid">${pages.map(p=>`<article class="adv"><span class="sub">${esc(p.kicker||'')}</span><b>${esc(p.name||'')}</b><p>${esc(p.blurb||'')}</p><div class="adv-go">${p.site?`<a href="${esc(p.site)}" target="_blank" rel="noopener noreferrer">On the website</a>`:''}${p.facebook?`<a href="${esc(p.facebook)}" target="_blank" rel="noopener noreferrer">Open on Facebook</a>`:''}</div></article>`).join('')}</div></div>`}
function cabView(){const o=rems(),[y,q]=curQ(),k=qk(y,q),rows=latestStories();
$('#m').innerHTML=offNote()+`<div class="card"><h3>Today in the cab</h3>${o.length?o.map(x=>`<p><b style="color:#E41E3F">Reminder.</b> ${esc(x.t)}</p>`).join(''):`<p>Nothing due today. Q${q} ${y}: <b>${ITEMS.length-pend(k)}/${ITEMS.length}</b> checks done.</p>`}<button class="btn cab-btn" onclick="go('rem')">Open checklist</button><button class="btn g cab-btn" onclick="enableAlerts(this)">Remind me when this page is closed</button><p id="al" class="sub"></p></div>${advocateWidgets()}${newsCard()}<div class="card" style="padding:0;overflow:hidden"><h3 style="padding:14px 14px 0">Latest stories</h3>${rows.length?rows.map(p=>`<button class="story-hit" onclick="rd('${js(p.id)}')"><span class="sub">${ico(sinfo(p).s,sinfo(p).n,sinfo(p).logo)}${esc(sinfo(p).n)} · ${p.m<2?'just now':ago(p.m)}</span><b>${esc(hl(p))}</b></button>`).join(''):'<p class="mut" style="padding:14px">No stories saved on this phone yet.</p>'}<div style="padding:12px 14px 14px"><button class="btn g cab-btn" onclick="go('feed')">Open the full feed</button></div></div>`;paintAlertStatus()}
function alertState(){const[y]=curQ();return{pending:pend(qk(...curQ())),total:ITEMS.length,reconciled:!!R.rec[y]}}
function savePlan(plan){return new Promise((resolve,reject)=>{const req=indexedDB.open('goroadhub',1);req.onupgradeneeded=()=>{if(!req.result.objectStoreNames.contains('alerts'))req.result.createObjectStore('alerts')};req.onerror=()=>reject(req.error);req.onsuccess=()=>{const db=req.result,tx=db.transaction('alerts','readwrite');tx.objectStore('alerts').put(plan,'plan');tx.oncomplete=()=>{db.close();resolve()};tx.onerror=()=>reject(tx.error)}})}
async function scheduleAlerts(){if(!('serviceWorker'in navigator)||!('Notification'in window)||Notification.permission!=='granted')return;const state=alertState(),plan=alertPlan(new Date(),state);try{await savePlan({...state,updated:Date.now()})}catch(e){}let reg;try{reg=await navigator.serviceWorker.ready}catch(e){return}let existing=[];try{existing=await reg.getNotifications({includeTriggered:true})}catch(e){try{existing=await reg.getNotifications()}catch(err){existing=[]}}existing.filter(n=>String(n.tag||'').startsWith('goroadhub-q')).forEach(n=>n.close());if(typeof TimestampTrigger==='function'){for(const item of plan){try{await reg.showNotification(item.title,{body:item.body,tag:item.tag,showTrigger:new TimestampTrigger(item.at),data:{cab:true}})}catch(e){}}}if(reg.periodicSync){try{await reg.periodicSync.register('goroadhub-quarter',{minInterval:12*60*60*1000})}catch(e){}}}
async function enableAlerts(){const el=$('#al');if(!('Notification'in window)||!('serviceWorker'in navigator)){if(el)el.textContent="This browser can only show the reminder while The Driver's Advocate is open.";return}let perm=Notification.permission;if(perm==='default')perm=await Notification.requestPermission();if(perm!=='granted'){if(el)el.textContent='Alerts stay off until you allow notifications.';return}await scheduleAlerts();let closed=typeof TimestampTrigger==='function';try{closed=closed||!!(await navigator.serviceWorker.ready).periodicSync}catch(e){}if(el)el.textContent=closed?"On. At 8:00 on the last three mornings of the quarter, and on quarter-end morning, The Driver's Advocate can remind you even if this page is closed.":"Notifications are allowed, but this browser still only delivers them while The Driver's Advocate is open."}
function paintAlertStatus(){const el=$('#al');if(!el||!('Notification'in window)||Notification.permission!=='granted')return;el.textContent='Closed-page reminders are on for this phone.'}
function ageOf(o){return {...o,m:Math.max(0,Math.round((Date.now()-(o.at||Date.now()))/6e4))}}
async function loadSnapshot(){try{const r=await fetch('/news-snapshot.json',{cache:'no-store'});if(!r.ok)return;const data=await r.json();if(Array.isArray(data.posts)&&data.posts.length){const have=new Set((PS||[]).map(p=>String(p.id)));const add=data.posts.map(ageOf).filter(p=>!have.has(String(p.id)));if(add.length)PS=[...(PS||[]),...add]}if((!TR||!TR.length)&&Array.isArray(data.traffic))TR=data.traffic.map(ageOf);drawTk();refresh()}catch(e){}}
async function load(){try{const lim=ADMIN?'?limit=1000':'?limit=80';const[a,b,ep,fd,cm]=await Promise.all([api('GET','/api/posts'+lim),api('GET','/api/ticker'),api('GET','/api/episodes?limit=60'),api('GET','/api/feeds'),api('GET','/api/comments?limit=200')]);let tr=[];try{tr=await api('GET','/api/traffic?limit=40')}catch(e){}FD=fd;CM=cm;TR=tr.map(ageOf);EPS.splice(0,EPS.length,...ep.map(o=>({...o,m:Math.max(0,Math.round((Date.now()-(o.at||0))/6e4))})).sort((x,y)=>(y.at||0)-(x.at||0)));const playing=EPS.findIndex(x=>sameUrl(x.audio,AU.currentSrc||AU.src));if(playing>=0)CUR=playing;PS=a.map(ageOf);TK=b.sort((x,y)=>(y.at||0)-(x.at||0));OFFLINE=false;saveSnap();if(!(PS||[]).some(p=>p.auto&&p.src==='news')&&!TR.length)await loadSnapshot();refresh();drawTk()}catch(e){if(!PS)restoreSnap();OFFLINE=true;await loadSnapshot();refresh();drawTk()}}
const wr=f=>(...a)=>f(...a).then(x=>{load();return x});
DB={collection:c=>({add:wr(d=>api('POST','/api/'+c,d))}),doc:p=>{const[c,i]=p.split('/');return{update:wr(d=>api('PATCH','/api/'+c+'/'+i,d)),delete:wr(()=>api('DELETE','/api/'+c+'/'+i))}}};
function rememberName(name){const n=(name!=null?name:($('#hu')&&$('#hu').value||'')).trim();if(n){S.me=n;sv()}}
function enterHub(asAdmin,name){rememberName(name);document.body.classList.add('in');const g=$('#gate');if(g)g.hidden=true;nav();go(asAdmin?'adm':'mag')}
function gateTab(which){const join=which==='new',inf=$('#gate-in'),jf=$('#gate-new'),a=$('#gt-in'),b=$('#gt-new');if(inf)inf.hidden=join;if(jf)jf.hidden=!join;if(a){a.classList.toggle('on',!join);a.setAttribute('aria-selected',String(!join))}if(b){b.classList.toggle('on',join);b.setAttribute('aria-selected',String(join))}const focus=join?$('#ju'):$('#hu');if(focus)focus.focus()}
async function gateLogin(ev){ev.preventDefault();const username=($('#hu').value||'').trim(),password=$('#hp').value;if(!password){$('#he').textContent='Enter a username and password, or continue without logging in.';return}try{const signed=await api('POST','/api/login',{username,password});const me=await api('GET','/api/me');if(signed.admin){if(!me.admin){$('#he').textContent='Password was accepted, but the browser did not keep the login cookie. Open the site over HTTPS and try again.';return}ADMIN=true;enterHub(true);return}if(signed.user&&me.user===signed.user&&!me.admin){ADMIN=false;enterHub(false,signed.user);return}$('#he').textContent='Password was accepted, but the browser did not keep the login cookie. Open the site over HTTPS and try again.'}catch(e){const m={401:'Wrong username or password',429:'Too many attempts, wait a few minutes'};$('#he').textContent=m[e.code]||'Login failed'}}
async function gateJoin(ev){ev.preventDefault();const username=($('#ju').value||'').trim(),password=$('#jp').value;if(username.length<2){$('#je').textContent='Use a username of at least 2 characters.';return}if(password.length<8){$('#je').textContent='Use a password of at least 8 characters.';return}try{const signed=await api('POST','/api/register',{username,password});const me=await api('GET','/api/me');if(!signed.user||me.user!==signed.user||me.admin){$('#je').textContent='The account was saved, but the browser did not keep the login. Try Log in.';return}ADMIN=false;enterHub(false,signed.user)}catch(e){const m={400:'Use 2–40 letters or numbers, and a password of at least 8 characters',409:'That username is taken',429:'Too many attempts, wait a few minutes'};$('#je').textContent=m[e.code]||e.error||'Could not create the account'}}
async function doLogin(){try{const signed=await api('POST','/api/login',{username:($('#lu')&&$('#lu').value||'').trim(),password:$('#lp').value});const me=await api('GET','/api/me');if(signed.admin){if(!me.admin){$('#le').textContent=' Password was accepted, but the browser did not keep the login cookie. Open the site over HTTPS and try again.';return}ADMIN=true;nav();go('adm');return}if(signed.user&&me.user===signed.user&&!me.admin){ADMIN=false;S.me=signed.user;sv();nav();go('mag');return}$('#le').textContent=' Password was accepted, but the browser did not keep the login cookie. Open the site over HTTPS and try again.'}catch(e){const m={401:' Wrong username or password',429:' Too many attempts, wait a few minutes'};$('#le').textContent=m[e.code]||(' Login failed'+(e.code?' ('+e.code+')':''))}}
async function logout(){try{await api('POST','/api/logout')}catch(e){}ADMIN=false;document.body.classList.remove('in');const g=$('#gate');if(g){g.hidden=false;const p=$('#hp');if(p)p.value='';const h=$('#he');if(h)h.textContent=''}nav()}
async function loadAdvocate(){try{const live=await api('GET','/api/advocate');if(live&&live.pages&&live.pages.length){ADV=live;if(V.view=='mag')magView();return}}catch(e){}try{const r=await fetch('/advocate.json');if(!r.ok)return;const pages=await r.json();if(Array.isArray(pages)&&pages.length){ADV={pages};if(V.view=='mag')magView()}}catch(e){}}
async function loadOutlets(){try{const r=await fetch('/outlets.json');if(!r.ok)return;const rows=await r.json();if(Array.isArray(rows)&&rows.length){OUTLETS=rows;drawTk();if(document.body.classList.contains('in'))refresh()}}catch(e){}}
(async()=>{try{const me=await api('GET','/api/me');ADMIN=!!me.admin;if(me.user&&!me.admin){S.me=me.user;sv()}}catch(e){}nav();loadAdvocate();loadOutlets();await load();setInterval(load,30000)})();
document.addEventListener('keydown',e=>{if(e.key!=='Escape')return;const o=$('#rd')||$('#rp');if(o)o.remove()});
restoreSnap();
render();drawTk();
if(!document.body.classList.contains('in')&&$('#hu'))$('#hu').focus();
window.addEventListener('online',()=>load());
window.addEventListener('offline',()=>{OFFLINE=true;refresh();drawTk()});
if('serviceWorker'in navigator){
  navigator.serviceWorker.register('/sw.js').then(()=>{window.__swOn=true;if('Notification'in window&&Notification.permission==='granted')scheduleAlerts()}).catch(()=>{});
  navigator.serviceWorker.addEventListener('message',e=>{if(e.data&&e.data.cab){if(!document.body.classList.contains('in'))enterHub(false);else go('mag')}});
}
if(new URLSearchParams(location.search).has('cab'))enterHub(false);
